-- Phase 4b pages 601-604. Entries are created through the editor RPC, then marked: nquran also lists the same narrators at the
-- word -> reviewed as 'auto:nquran+book'; otherwise unreviewed (waiting for a person).
BEGIN;
SELECT set_config('app.device_id','auto-review',true);
CREATE TEMP TABLE _auto_new_ids(id text, approve boolean) ON COMMIT DROP;

INSERT INTO _auto_new_ids(id, approve) SELECT (qiraat_review_create_entry('{"surah":109,"ayah":3,"startWord":3,"endAyah":3,"endWord":3,"kind":"usul","categoryCode":"IMALAH_TAQLIL","rulingText":"هشام: إمالة فتحة العين والألف\n[المصدر: كتاب ابن عامر ص144]","hafsText":"عَـٰبِدُونَ","notes":"sources: Ebn Amer.csv:1610","deviceId":"auto-review","narrators":[{"id":"Q04-R01","action":"هشام: إمالة فتحة العين والألف","wajhOrder":1,"wajhNote":null}]}'::jsonb))->>'entryId', true;
INSERT INTO _auto_new_ids(id, approve) SELECT (qiraat_review_create_entry('{"surah":109,"ayah":4,"startWord":3,"endAyah":4,"endWord":3,"kind":"usul","categoryCode":"IMALAH_TAQLIL","rulingText":"هشام: إمالة فتحة العين والألف\n[المصدر: كتاب ابن عامر ص144]","hafsText":"عَابِدٌۭ","notes":"sources: Ebn Amer.csv:1611","deviceId":"auto-review","narrators":[{"id":"Q04-R01","action":"هشام: إمالة فتحة العين والألف","wajhOrder":1,"wajhNote":null}]}'::jsonb))->>'entryId', true;
INSERT INTO _auto_new_ids(id, approve) SELECT (qiraat_review_create_entry('{"surah":109,"ayah":5,"startWord":3,"endAyah":5,"endWord":3,"kind":"usul","categoryCode":"IMALAH_TAQLIL","rulingText":"هشام: إمالة فتحة العين والألف\n[المصدر: كتاب ابن عامر ص144]","hafsText":"عَـٰبِدُونَ","notes":"sources: Ebn Amer.csv:1612","deviceId":"auto-review","narrators":[{"id":"Q04-R01","action":"هشام: إمالة فتحة العين والألف","wajhOrder":1,"wajhNote":null}]}'::jsonb))->>'entryId', true;
INSERT INTO _auto_new_ids(id, approve) SELECT (qiraat_review_create_entry('{"surah":109,"ayah":6,"startWord":3,"endAyah":6,"endWord":4,"kind":"usul","categoryCode":"YAAT_IDAFA","rulingText":"أسكن الياء\n[المصدر: كتاب شعبة ص78]","hafsText":"وَلِىَ دِينِ","notes":"sources: Shu''bah.csv:643","deviceId":"auto-review","narrators":[{"id":"Q05-R01","action":"أسكن الياء","wajhOrder":1,"wajhNote":null}]}'::jsonb))->>'entryId', true;
INSERT INTO _auto_new_ids(id, approve) SELECT (qiraat_review_create_entry('{"surah":109,"ayah":6,"startWord":4,"endAyah":6,"endWord":4,"kind":"usul","categoryCode":"YAAT_ZAWAID","rulingText":"إثبات الياء وصلاً ووقفاً\n[المصدر: كتاب يعقوب ص165]","hafsText":"دِينِ","notes":"sources: Yaqoob Al-Hadramy.csv:2465","deviceId":"auto-review","narrators":[{"id":"Q09-R01","action":"إثبات الياء وصلاً ووقفاً","wajhOrder":1,"wajhNote":null},{"id":"Q09-R02","action":"إثبات الياء وصلاً ووقفاً","wajhOrder":1,"wajhNote":null}]}'::jsonb))->>'entryId', true;
INSERT INTO _auto_new_ids(id, approve) SELECT (qiraat_review_create_entry('{"surah":111,"ayah":2,"startWord":1,"endAyah":2,"endWord":2,"kind":"usul","categoryCode":"IMALAH_TAQLIL","rulingText":"إمالة فتحة النون والألف\n[المصدر: كتاب خلف العاشر ص189]","hafsText":"مَآ أَغْنَىٰ","notes":"sources: Al-Khalaf.csv:2959","deviceId":"auto-review","narrators":[{"id":"Q10-R01","action":"إمالة فتحة النون والألف","wajhOrder":1,"wajhNote":null},{"id":"Q10-R02","action":"إمالة فتحة النون والألف","wajhOrder":1,"wajhNote":null}]}'::jsonb))->>'entryId', false;
INSERT INTO _auto_new_ids(id, approve) SELECT (qiraat_review_create_entry('{"surah":111,"ayah":2,"startWord":2,"endAyah":2,"endWord":2,"kind":"usul","categoryCode":"IMALAH_TAQLIL","rulingText":"قرأهما الكسائي بالإمالة\n[المصدر: كتاب الكسائي ص313]","hafsText":"أَغْنَىٰ","notes":"sources: Al-Kisa''i.csv:4345 | Hamza.csv:2959","deviceId":"auto-review","narrators":[{"id":"Q06-R01","action":"إمالة فتحة النون والألف","wajhOrder":1,"wajhNote":null},{"id":"Q06-R02","action":"إمالة فتحة النون والألف","wajhOrder":1,"wajhNote":null},{"id":"Q07-R01","action":"قرأهما الكسائي بالإمالة","wajhOrder":1,"wajhNote":null},{"id":"Q07-R02","action":"قرأهما الكسائي بالإمالة","wajhOrder":1,"wajhNote":null}]}'::jsonb))->>'entryId', true;
INSERT INTO _auto_new_ids(id, approve) SELECT (qiraat_review_create_entry('{"surah":111,"ayah":3,"startWord":1,"endAyah":3,"endWord":1,"kind":"usul","categoryCode":"IMALAH_TAQLIL","rulingText":"إمالة فتحة اللام والألف\n[المصدر: كتاب خلف العاشر ص189]","hafsText":"سَيَصْلَىٰ","notes":"sources: Al-Khalaf.csv:2960 | Al-Kisa''i.csv:4346 | Hamza.csv:2960","deviceId":"auto-review","narrators":[{"id":"Q06-R01","action":"إمالة فتحة اللام والألف","wajhOrder":1,"wajhNote":null},{"id":"Q06-R02","action":"إمالة فتحة اللام والألف","wajhOrder":1,"wajhNote":null},{"id":"Q07-R01","action":"قرأهما الكسائي بالإمالة","wajhOrder":1,"wajhNote":null},{"id":"Q07-R02","action":"قرأهما الكسائي بالإمالة","wajhOrder":1,"wajhNote":null},{"id":"Q10-R01","action":"إمالة فتحة اللام والألف","wajhOrder":1,"wajhNote":null},{"id":"Q10-R02","action":"إمالة فتحة اللام والألف","wajhOrder":1,"wajhNote":null}]}'::jsonb))->>'entryId', true;
INSERT INTO _auto_new_ids(id, approve) SELECT (qiraat_review_create_entry('{"surah":111,"ayah":3,"startWord":1,"endAyah":3,"endWord":1,"kind":"usul","categoryCode":"TAGHLIZ_LAM","rulingText":"ورش: تغليظ اللام المفتوحة بعد الصاد أو الطاء أو الظاء\n[المصدر: كتاب ورش ص401]","hafsText":"سَيَصْلَىٰ","notes":"sources: Nafe3.csv:2475","deviceId":"auto-review","narrators":[{"id":"Q01-R02","action":"ورش: تغليظ اللام المفتوحة بعد الصاد أو الطاء أو الظاء","wajhOrder":1,"wajhNote":null}]}'::jsonb))->>'entryId', true;

UPDATE qiraat_entries SET review_status='unreviewed', verification_status='REVIEWED', review_source=NULL, review_note='أُضيف آليًا من كتاب القراءة — بانتظار المراجعة' WHERE id IN (SELECT id FROM _auto_new_ids WHERE NOT approve) AND created_at >= now();
UPDATE qiraat_entries SET review_status='reviewed', verification_status='REVIEWED', review_source='auto:nquran+book', review_note='أُضيف آليًا: طابق كتاب القراءة وnquran.com' WHERE id IN (SELECT id FROM _auto_new_ids WHERE approve) AND created_at >= now();
SELECT count(*) AS generated_entry_count FROM qiraat_entries WHERE id IN (SELECT id FROM _auto_new_ids);
COMMIT;
